def is_majority(arr, n, x):
    def count(x, arr, n):
        """Helper function to count occurrences of x in the sorted array."""
        low, high = 0, n - 1
        while low <= high:
            mid = low + (high - low) // 2
            if arr[mid] == x:
                return mid
            elif arr[mid] < x:
                low = mid + 1
            else:
                high = mid - 1
        return -1

    index = count(x, arr, n)
    if index == -1:
        return False

    # Since the array is sorted and we know it's majority, we can use binary search
    # to quickly find where the element would be if it were a majority.
    left = 0
    right = n - 1
    while left < right - 1:
        mid = (left + right) // 2
        if arr[mid] >= x:
            right = mid
        else:
            left = mid
    majority_index = right

    # Check if the majority index has more occurrences than n//2
    return (arr[majority_index] == x) and (majority_index * 2 > n)

